CREATE TABLE user_customization (user_id TEXT PRIMARY KEY NOT NULL REFERENCES users(id) ON DELETE CASCADE, avatar TEXT NOT NULL DEFAULT 'mint' CHECK(avatar IN ('mint','lavender','stone','sunset')), theme TEXT NOT NULL DEFAULT 'meadow' CHECK(theme IN ('meadow','forest','dusk')), palette TEXT NOT NULL DEFAULT 'sage' CHECK(palette IN ('sage','white','sand','cocoa')), tagline TEXT NOT NULL DEFAULT '' CHECK(length(tagline)<=80), default_view TEXT NOT NULL DEFAULT 'month' CHECK(default_view IN ('month','week','schedule')), reduced_motion INTEGER NOT NULL DEFAULT 0 CHECK(reduced_motion IN (0,1)), compact_calendar INTEGER NOT NULL DEFAULT 0 CHECK(compact_calendar IN (0,1)));
